export const TENANT_TABLE_NAMES = TENANT_TABLES.map((entry) => entry.table);
export const TENANT_TABLE_BY_NAME: ReadonlyMap<string, TenantTableRegistryEntry> = new Map(TENANT_TABLES.map((entry) => [entry.table, entry]));

